import java.util.*;

public class Main {
    static final int Z = 100;
    static final int N = Z * Z;
    static final int M = Z * Z * Z * 3;
    static final int INF = Integer.MAX_VALUE;

    static class Edge {
        int to, cost, flow, rev;
        public Edge(int to, int cost, int flow, int rev) {
            this.to = to;
            this.cost = cost;
            this.flow = flow;
            this.rev = rev;
        }
    }

    static List<Edge>[] graph;
    static int[] px = new int[N], py = new int[N], head = new int[N], d_arr = new int[N], vis = new int[N], pre = new int[N], id = new int[N];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        graph = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            graph[i] = new ArrayList<>();
        }

        int s = 0;
        int t = n * 100 + 1;

        // Initialize graph
        for (int i = 0; i < N; i++) {
            graph[i].clear();
        }

        // Add edge function
        class AddEdge {
            void add(int u, int v, int flow, int cost) {
                graph[u].add(new Edge(v, cost, flow, graph[v].size()));
                graph[v].add(new Edge(u, -cost, 0, graph[u].size() - 1));
            }
        }
        AddEdge adder = new AddEdge();

        // Build the network
        for (int i = 1; i <= 100; i++) {
            adder.add(i, t, 100, 0);
        }

        for (int i = 1; i <= k; i++) {
            int v = sc.nextInt();
            adder.add(s, (v - 1) * 100 + 1, 1, 0);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                adder.add((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
            }
        }

        for (int i = 1; i <= m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            for (int j = 1; j < 100; j++) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int k_ = 1; k_ <= 50; k_++) {
                    int costVal = c + (k_ * k_ - (k_ - 1) * (k_ - 1)) * d;
                    adder.add(idx, idy, 1, costVal);
                }
            }
            for (int j = 1; j < 100; j++) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int k_ = 1; k_ <= 50; k_++) {
                    int costVal = c + (k_ * k_ - (k_ - 1) * (k_ - 1)) * d;
                    adder.add(idx, idy, 1, costVal);
                }
            }
        }

        System.out.println(maxFlow(s, t));
    }

    static int maxFlow(int s, int t) {
        int flow = 0;
        int costSum = 0;
        while (spfa(s, t)) {
            int f = INF;
            for (int i = t; i != s; i = pre[i]) {
                f = Math.min(f, graph[pre[i]].get(id[i]).flow);
            }
            for (int i = t; i != s; i = pre[i]) {
                Edge e = graph[pre[i]].get(id[i]);
                e.flow -= f;
                graph[e.to].get(e.rev).flow += f;
            }
            costSum += d_arr[t] * f;
            flow += f;
        }
        return costSum;
    }

    static boolean spfa(int s, int t) {
        Arrays.fill(d_arr, INF);
        Arrays.fill(vis, 0);
        Arrays.fill(pre, -1);
        Arrays.fill(id, -1);
        d_arr[s] = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(s);
        vis[s] = 1;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            vis[u] = 0;
            List<Edge> edges = graph[u];
            for (int i = 0; i < edges.size(); i++) {
                Edge e = edges.get(i);
                if (e.flow > 0 && d_arr[e.to] > d_arr[u] + e.cost) {
                    d_arr[e.to] = d_arr[u] + e.cost;
                    pre[e.to] = u;
                    id[e.to] = i;
                    if (vis[e.to] == 0) {
                        vis[e.to] = 1;
                        queue.offer(e.to);
                    }
                }
            }
        }
        return d_arr[t] < INF;
    }
}
